public static class WorkPaths {
 [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern SafeFileHandle CreateFile(string name,uint access,uint share,IntPtr security,uint creation,uint flags,IntPtr template);
 [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern uint GetFinalPathNameByHandle(SafeFileHandle handle,StringBuilder result,uint size,uint flags);
 public static string CanonicalDirectory(string path){if(!Path.IsPathRooted(path)||!Directory.Exists(path))throw new ArgumentException("需要已有绝对目录");using(var handle=CreateFile(path,0,7,IntPtr.Zero,3,0x02000000,IntPtr.Zero)){if(handle.IsInvalid)throw new IOException("无法核验目录");var b=new StringBuilder(32768);uint n=GetFinalPathNameByHandle(handle,b,(uint)b.Capacity,0);if(n==0||n>=b.Capacity)throw new IOException("无法核验目录落点");string result=b.ToString();if(result.StartsWith(@"\\?\UNC\",StringComparison.OrdinalIgnoreCase))result=@"\\"+result.Substring(8);else if(result.StartsWith(@"\\?\",StringComparison.OrdinalIgnoreCase))result=result.Substring(4);return Path.GetFullPath(result).TrimEnd(Path.DirectorySeparatorChar);}}
 static bool Inside(string path,string root){return path.Equals(root,StringComparison.OrdinalIgnoreCase)||path.StartsWith(root+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase);}
 public static string PrivateDirectory(string path){string root=CanonicalDirectory(path),product=CanonicalDirectory(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,".."));string driveRoot=Path.GetPathRoot(root);if(root.StartsWith(@"\\",StringComparison.Ordinal)||String.IsNullOrEmpty(driveRoot))throw new ArgumentException("工作目录须位于本地磁盘");var drive=new DriveInfo(driveRoot);if((drive.DriveType!=DriveType.Fixed&&drive.DriveType!=DriveType.Removable)||Inside(root,product)||root.Equals(driveRoot.TrimEnd(Path.DirectorySeparatorChar),StringComparison.OrdinalIgnoreCase))throw new ArgumentException("工作目录不能位于产品区或文件系统根目录");return root;}
 public static string OutputFile(string root,string path){if(!Path.IsPathRooted(path))throw new ArgumentException("输出需要绝对路径");string full=Path.GetFullPath(path),parent=CanonicalDirectory(Path.GetDirectoryName(full)),product=CanonicalDirectory(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,".."));if(!Inside(parent,root)||Inside(parent,product))throw new ArgumentException("输出需位于私密工作目录");return Path.Combine(parent,Path.GetFileName(full));}
}

