 public static bool NeedsBaselineRefresh(DateTime observed,DateTime completed){return (completed-observed).TotalSeconds>=30;}
 static Item Result(string key,string status,string source,string value,string limitation,string next){return new Item(key,status,source,value,limitation,next);}
 public static Item HttpEvidence(string key,string host,string family,long dnsMs,long tcpMs,long tlsMs,long totalMs,int code){string meaning=code==401?"需要认证":code==403?"访问受限":code==404?"探针根路径未提供资源；TLS已连通，未验证模型":code==421?"探针请求未被服务器接受；TLS已连通，未验证模型":code==429?"请求限流":code>=500?"服务端响应错误":code>=400?"请求未成功":"已收到响应；认证和模型未验证";string state=code==401||code==404||code<400?"pass":"unknown";string next=code==404?"根路径结果不代表模型可用；按需在对应应用内核对。":code==401?"已收到认证要求；请在对应应用内核对登录和模型响应。":code==403?"请求受限；请核对对应应用的访问权限。":code==421?"探针请求未被服务器接受，不能据此判断实际 AI 工具是否可用；请在对应工具中核对。":code==429?"服务限流；稍后重试。":code>=500?"服务返回错误；稍后核对服务响应。":"如需核实，请检查对应服务或稍后重试。";var item=Result(key,state,host,"仅测 "+family+"；DNS "+dnsMs+"ms / TCP "+tcpMs+"ms / TLS "+tlsMs+"ms；HTTP "+code+"（"+meaning+"）；总计 "+totalMs+"ms","仅测试第一个解析地址，另一地址族未测；直接 TLS 不代表代理路径、登录成功、模型可用或官方整体状态。",next);item.identity="ai-tls-complete";item.subject="http-"+code;item.role="仅测 "+family+"；DNS "+dnsMs+"ms / TCP "+tcpMs+"ms / TLS "+tlsMs+"ms 已连通";item.transportState="pass";item.evidencePhase="HTTP";item.evidenceScope=family+";direct;HEAD /;first-address";item.rawResult=code.ToString();return item;}
 public static string FailureKind(Exception e,bool cancelled){var socket=e as SocketException;return cancelled?"用户取消":e is TimeoutException||socket!=null&&socket.SocketErrorCode==SocketError.TimedOut?"超时":e is AuthenticationException?"证书或 TLS 校验失败":socket!=null?"网络或解析失败":e is InvalidDataException?"HTTP 响应格式无效":e is IOException?"连接读取失败":e.GetType().Name;}
 public static string FailureCode(Exception e,bool cancelled,string stage,SslPolicyErrors certificateErrors){if(cancelled||e is OperationCanceledException)return "cancelled";if(certificateErrors!=SslPolicyErrors.None)return "certificate-"+((int)certificateErrors).ToString();for(var x=e;x!=null;x=x.InnerException){var socket=x as SocketException;if(x is TimeoutException||socket!=null&&socket.SocketErrorCode==SocketError.TimedOut)return "timeout";if(socket!=null)return stage=="DNS"?"dns-"+((int)socket.SocketErrorCode).ToString():"socket-"+((int)socket.SocketErrorCode).ToString();if(x is AuthenticationException)return "tls-authentication";}return stage=="HTTP"?"http-read-or-format":"tool-or-io";}
 // The compiler-built EXE has legacy target defaults; pin a modern protocol
 // without changing machine policy or the normal platform certificate validation.
 public static IAsyncResult BeginServiceAuthentication(SslStream ssl,string host){return ssl.BeginAuthenticateAsClient(host,null,SslProtocols.Tls12,false,null,null);}
 public static string TlsFailureDetail(Exception error){var parts=new List<string>();for(var e=error;e!=null&&parts.Count<4;e=e.InnerException)parts.Add(e.GetType().Name+"(0x"+unchecked((uint)e.HResult).ToString("X8")+")");return "TLS 策略：TLS 1.2；异常链："+String.Join(" → ",parts.ToArray());}
 static int Wait(IAsyncResult a,CancellationToken token,int ms){int n=WaitHandle.WaitAny(new[]{a.AsyncWaitHandle,token.WaitHandle},ms);if(n==1)throw new OperationCanceledException();if(n!=0)throw new TimeoutException();return n;}
 public static Item Service(string key,string host,CancellationToken token){return ServiceCore(key,host,token,null,443,null,"1.0");}
#if READINESS_TEST
 public static Item LoopbackServiceFixture(string key,int port,System.Security.Cryptography.X509Certificates.X509Certificate2 certificate,CancellationToken token){return LoopbackServiceProtocolFixture(key,port,certificate,token,"1.0");}
 public static Item LoopbackServiceProtocolFixture(string key,int port,System.Security.Cryptography.X509Certificates.X509Certificate2 certificate,CancellationToken token,string protocol){if(port<1||port>65535||(protocol!="1.0"&&protocol!="1.1"))throw new ArgumentException();return ServiceCore(key,"localhost",token,IPAddress.Loopback,port,delegate(System.Security.Cryptography.X509Certificates.X509Certificate presented){return certificate!=null&&presented!=null&&String.Equals(certificate.GetCertHashString(),presented.GetCertHashString(),StringComparison.OrdinalIgnoreCase);},protocol);}
#endif
 static Item ServiceCore(string key,string host,CancellationToken token,IPAddress fixtureAddress,int port,Func<System.Security.Cryptography.X509Certificates.X509Certificate,bool> fixtureTrust,string protocol){
  var watch=Stopwatch.StartNew();string stage="DNS",family="地址族未确定";long dnsMs=-1,tcpMs=-1,tlsMs=-1;SslPolicyErrors certificateErrors=SslPolicyErrors.None;try{
   IPAddress address;if(fixtureAddress==null){var dns=Dns.BeginGetHostAddresses(host,null,null);Wait(dns,token,Timeout);var addresses=Dns.EndGetHostAddresses(dns);address=addresses.FirstOrDefault();}else{if(!IPAddress.IsLoopback(fixtureAddress))throw new ArgumentException("fixture must be loopback");address=fixtureAddress;}if(address==null)throw new SocketException((int)SocketError.HostNotFound);family=address.AddressFamily==AddressFamily.InterNetwork?"IPv4":"IPv6";dnsMs=watch.ElapsedMilliseconds;
   stage="TCP";using(var client=new TcpClient(address.AddressFamily))using(token.Register(delegate{try{client.Close();}catch{}})){
    var connected=client.BeginConnect(address,port,null,null);Wait(connected,token,Timeout);client.EndConnect(connected);tcpMs=watch.ElapsedMilliseconds-dnsMs;
    stage="TLS";using(var ssl=new SslStream(client.GetStream(),false,delegate(object sender,System.Security.Cryptography.X509Certificates.X509Certificate certificate,System.Security.Cryptography.X509Certificates.X509Chain chain,SslPolicyErrors errors){bool accepted=errors==SslPolicyErrors.None||fixtureAddress!=null&&IPAddress.IsLoopback(fixtureAddress)&&fixtureTrust!=null&&fixtureTrust(certificate);certificateErrors=accepted?SslPolicyErrors.None:errors;return accepted;})){ssl.ReadTimeout=Timeout;ssl.WriteTimeout=Timeout;var auth=BeginServiceAuthentication(ssl,host);Wait(auth,token,Timeout);ssl.EndAuthenticateAsClient(auth);tlsMs=watch.ElapsedMilliseconds-dnsMs-tcpMs;
     stage="HTTP";byte[] req=Encoding.ASCII.GetBytes("HEAD / HTTP/"+protocol+"\r\nHost: "+host+"\r\nUser-Agent: WorkEnv-Observation/0.6\r\nConnection: close\r\n\r\n");ssl.Write(req,0,req.Length);ssl.Flush();var bytes=new List<byte>();while(bytes.Count<1024){int b=ssl.ReadByte();if(b<0||b==10)break;bytes.Add((byte)b);}string line=Encoding.ASCII.GetString(bytes.ToArray()).Trim();var chunks=line.Split(' ');int code;if(chunks.Length<2||!chunks[0].StartsWith("HTTP/1.")||!Int32.TryParse(chunks[1],out code)||code<100||code>599)throw new InvalidDataException("HTTP 状态无法解析");
     return HttpEvidence(key,host,family,dnsMs,tcpMs,tlsMs,watch.ElapsedMilliseconds,code);
    }
   }
  }catch(Exception e){string why=FailureKind(e,token.IsCancellationRequested);string completed=(dnsMs>=0?"DNS "+dnsMs+"ms；":"")+(tcpMs>=0?"TCP "+tcpMs+"ms；":"")+(tlsMs>=0?"TLS "+tlsMs+"ms；":"");string diagnostic=stage=="TLS"&&!token.IsCancellationRequested?"；"+TlsFailureDetail(e):"";bool certificateFailed=certificateErrors!=SslPolicyErrors.None&&!token.IsCancellationRequested;var item=Result(key,certificateFailed?"attention":"unknown",host,completed+stage+"： "+why+"；"+family+"；总计 "+watch.ElapsedMilliseconds+"ms"+diagnostic,"仅测试第一个解析地址；其他地址与地址族未测，不代表服务整体宕机。","核对网络、系统时间及代理路径后重试。");item.transportState=certificateFailed?"attention":tlsMs>=0?"pass":"unknown";item.evidencePhase=stage;item.evidenceScope=family+";direct;first-address";item.failureCode=FailureCode(e,token.IsCancellationRequested,stage,certificateErrors);item.rawResult="dns="+(dnsMs>=0)+";tcp="+(tcpMs>=0)+";tls="+(tlsMs>=0);if(tlsMs>=0){item.identity="ai-tls-complete";item.role="仅测 "+family+"；DNS "+dnsMs+"ms / TCP "+tcpMs+"ms / TLS "+tlsMs+"ms 已连通";}else item.identity="ai-stage-"+stage;return item;}
 }
 static string OwnProcess(string file,string args,int timeout,CancellationToken token){
  var p=new Process();p.StartInfo=new ProcessStartInfo{FileName=file,Arguments=args,UseShellExecute=false,RedirectStandardOutput=true,RedirectStandardError=true,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden};var output=new StringBuilder();p.OutputDataReceived+=delegate(object s,DataReceivedEventArgs e){if(e.Data!=null)lock(output)if(output.Length<16384)output.AppendLine(e.Data);};p.ErrorDataReceived+=delegate(object s,DataReceivedEventArgs e){if(e.Data!=null)lock(output)if(output.Length<16384)output.AppendLine(e.Data);};
  try{if(!p.Start())throw new InvalidOperationException("进程启动失败");p.BeginOutputReadLine();p.BeginErrorReadLine();var until=Stopwatch.StartNew();while(!p.WaitForExit(100)){if(token.IsCancellationRequested||until.ElapsedMilliseconds>=timeout){try{p.Kill();}catch{}if(token.IsCancellationRequested)throw new OperationCanceledException();throw new TimeoutException();}}p.WaitForExit();lock(output)return output.ToString();}finally{p.Dispose();}
 }
 public static Item DnsConfiguration(IEnumerable<string> values){var entries=values.Where(s=>!String.IsNullOrWhiteSpace(s)).Distinct().Take(8).ToList();return Result("ext-dns-config",entries.Count==0?"unknown":"pass","Windows 网络适配器 DNS 配置",entries.Count==0?"未列出 DNS 服务器":String.Join("；",entries.ToArray()),"配置不是递归出口，不覆盖应用或浏览器内置 DoH。","按需核对应用配置。");}
 public static List<Item> DnsEvidence(CancellationToken token){var r=new List<Item>();try{
   var entries=new List<string>();foreach(var nic in NetworkInterface.GetAllNetworkInterfaces()){token.ThrowIfCancellationRequested();foreach(var ip in nic.GetIPProperties().DnsAddresses)if(!entries.Contains(ip.ToString()))entries.Add(ip.ToString());}
   r.Add(DnsConfiguration(entries));
  }catch(Exception e){r.Add(Result("ext-dns-config","unknown","Windows 网络适配器",e is OperationCanceledException?"已取消":"读取失败","未完成配置读取。","核对权限后重试。"));}
  try{var pending=Dns.BeginGetHostAddresses("api.openai.com",null,null);Wait(pending,token,Timeout);var ips=Dns.EndGetHostAddresses(pending);r.Add(Result("ext-dns-lookup",ips.Length>0?"pass":"unknown","系统解析 api.openai.com","返回地址数："+ips.Length,"解析成功不证明应用实际路径。","结合应用内设置核对。"));}catch(Exception e){r.Add(Result("ext-dns-lookup","unknown","系统解析 api.openai.com",e is OperationCanceledException?"已取消":e is TimeoutException?"超时":"解析失败","未能完成解析。","核对系统 DNS 后重试。"));}
  try{string exe=Path.Combine(Environment.SystemDirectory,"nslookup.exe");string text=OwnProcess(exe,"-type=TXT -timeout=3 -retry=1 whoami.ds.akahelp.net",7000,token);var found=ParseAkamaiNs(text);r.Add(Result("ext-dns-exit",found.Count>0?"pass":"unknown","nslookup 默认解析器 / Akamai TXT",found.Count>0?String.Join("；",found.Take(4).ToArray()):"未获得可验证的 ns 出口地址","仅 nslookup 默认解析链；递归缓存、转发及多解析器可能影响，不覆盖 Windows API、NRPT 或浏览器 DoH；ECS 与 ip 字段不作为解析器出口。","按需对照应用内 DNS 设置。"));}catch(Exception e){r.Add(Result("ext-dns-exit","unknown","nslookup 默认解析器 / Akamai TXT",e is OperationCanceledException?"已取消":e is TimeoutException?"超时":"观察失败","未取得递归出口证据。","检查系统解析后重试。"));}
  return r;
 }
 public static List<string> ParseAkamaiNs(string text){var result=new List<string>();foreach(System.Text.RegularExpressions.Match m in System.Text.RegularExpressions.Regex.Matches(text??"","\\\"ns\\\"\\s*\\\"([^\\\"]+)\\\"",System.Text.RegularExpressions.RegexOptions.IgnoreCase)){IPAddress a;if(IPAddress.TryParse(m.Groups[1].Value,out a)&&!result.Contains(a.ToString()))result.Add(a.ToString());}return result;}
 static uint V4(string s){IPAddress a;if(!IPAddress.TryParse(s,out a)||a.AddressFamily!=AddressFamily.InterNetwork)throw new FormatException();byte[] b=a.GetAddressBytes();return ((uint)b[0]<<24)|((uint)b[1]<<16)|((uint)b[2]<<8)|b[3];}
 public static string[] CsvFields(string line){var fields=new List<string>();var text=new StringBuilder();bool quoted=false;for(int i=0;i<line.Length;i++){char c=line[i];if(c=='"'){if(quoted&&i+1<line.Length&&line[i+1]=='"'){text.Append('"');i++;}else quoted=!quoted;}else if(c==','&&!quoted){fields.Add(text.ToString());text.Length=0;}else text.Append(c);}if(quoted)throw new FormatException();fields.Add(text.ToString());return fields.ToArray();}
 public static string[] LookupCsv(Stream stream,string ip,CancellationToken token){uint target=V4(ip);using(var reader=new StreamReader(stream,Encoding.UTF8)){string line;int n=0;while((line=reader.ReadLine())!=null){if((++n&4095)==0)token.ThrowIfCancellationRequested();var f=CsvFields(line);if(f.Length<3||f[0].IndexOf(':')>=0)continue;uint lo,hi;try{lo=V4(f[0]);hi=V4(f[1]);}catch(FormatException){continue;}if(target>=lo&&target<=hi)return f;}return null;}}
 static readonly object lookupGate=new object();static readonly Dictionary<string,string[]> lookupCache=new Dictionary<string,string[]>();static readonly Queue<string> lookupOrder=new Queue<string>();public static int LookupCacheHits,LookupDecodeCount;public static int LookupCacheCount{get{lock(lookupGate)return lookupCache.Count;}}
 public static string[] LookupVerified(Stream input,string expected,string ip,CancellationToken token){token.ThrowIfCancellationRequested();IPAddress parsed;if(!IPAddress.TryParse(ip,out parsed)||parsed.AddressFamily!=AddressFamily.InterNetwork)throw new FormatException("需要 IPv4");byte[] snapshot;using(var memory=new MemoryStream()){var buffer=new byte[65536];int n;while((n=input.Read(buffer,0,buffer.Length))>0){token.ThrowIfCancellationRequested();if(memory.Length+n>32*1024*1024)throw new InvalidDataException("数据库快照过大");memory.Write(buffer,0,n);}snapshot=memory.ToArray();}token.ThrowIfCancellationRequested();string actual;using(var sha=SHA256.Create())actual=BitConverter.ToString(sha.ComputeHash(snapshot)).Replace("-","");if(!String.Equals(actual,expected,StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("数据库校验不符");token.ThrowIfCancellationRequested();string key=actual+"|"+parsed;string[] row;lock(lookupGate){token.ThrowIfCancellationRequested();if(lookupCache.TryGetValue(key,out row)){Interlocked.Increment(ref LookupCacheHits);return row==null?null:(string[])row.Clone();}}Interlocked.Increment(ref LookupDecodeCount);using(var source=new MemoryStream(snapshot,false))using(var gz=new GZipStream(source,CompressionMode.Decompress))row=LookupCsv(gz,ip,token);token.ThrowIfCancellationRequested();if(row==null||(row.Length<=16&&row.Sum(x=>x.Length)<=4096))lock(lookupGate){token.ThrowIfCancellationRequested();if(!lookupCache.ContainsKey(key)){while(lookupCache.Count>=128)lookupCache.Remove(lookupOrder.Dequeue());lookupCache.Add(key,row==null?null:(string[])row.Clone());lookupOrder.Enqueue(key);}}return row==null?null:(string[])row.Clone();}
 static string[] LookupAsset(string file,string ip,CancellationToken token){string path=Path.GetFullPath(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"assets",file));string expected=file.StartsWith("dbip-country-")?"E5C8459D638A272ECE7F4D7CFA49DCE18D91B4F403F6940BA9249BF0DB3781FD":"0EA3BA480ED39127FB2FF6BCBEA44DB14BC978F387EFEDC28F0411C054C4B1E4";using(var input=File.OpenRead(path))return LookupVerified(input,expected,ip,token);}
 public static bool DatabaseFresh(DateTime utc){return utc<new DateTime(2027,1,1,0,0,0,DateTimeKind.Utc);}
 public static List<Item> AttributeEvidence(Report baseline,CancellationToken token){return AttributeEvidenceWith(baseline,token,LookupAsset);}
 public static List<Item> AttributeEvidenceWith(Report baseline,CancellationToken token,Func<string,string,CancellationToken,string[]> lookup){

  var items=baseline.items.Where(i=>i.key=="ipv4-source"&&i.status=="pass").ToList();string ip=items.Count==2&&items[0].observation==items[1].observation?items[0].observation:null;var result=new List<Item>();string note="DB-IP Lite 2026-11，CC BY 4.0；覆盖和准确性有限，不代表账号结果。";
  if(ip==null){result.Add(Result("ext-attr-country","unknown","DB-IP Lite","双源出口不一致或未取得",note,"请先核对出口。"));result.Add(Result("ext-attr-asn","unknown","DB-IP Lite","缺少可比较出口",note,"请先核对出口。"));return result;}
  try{var country=lookup("dbip-country-lite-2026-11.csv.gz",ip,token);result.Add(Result("ext-attr-country",country==null?"unknown":"pass","DB-IP Country Lite 2026-11",country==null?"未匹配":country[2],note,"按需核对其他来源。"));}catch(Exception e){result.Add(Result("ext-attr-country","unknown","DB-IP Country Lite",e is OperationCanceledException?"已取消":"数据库缺失或读取失败",note,"核对数据文件。"));}
  try{var asn=lookup("dbip-asn-lite-2026-11.csv.gz",ip,token);result.Add(Result("ext-attr-asn",asn==null||asn.Length<4?"unknown":"pass","DB-IP ASN Lite 2026-11",asn==null||asn.Length<4?"未匹配":"AS"+asn[2]+" · "+asn[3],note,"按需核对其他来源。"));}catch(Exception e){result.Add(Result("ext-attr-asn","unknown","DB-IP ASN Lite",e is OperationCanceledException?"已取消":"数据库缺失或读取失败",note,"核对数据文件。"));}
  bool fresh=DatabaseFresh(DateTime.UtcNow);if(!fresh)foreach(var entry in result){entry.status="unknown";entry.observation+="（数据版本已过期）";}result.Add(Result("ext-attr-meta",fresh&&result.All(i=>i.status=="pass")?"pass":"unknown","DB-IP Lite","数据版本 2026-11；"+(fresh?"部分覆盖和准确性有限":"版本已过期"),note,"按月核对数据更新。"));return result;

 }
 public static List<Item> ParallelServices(Func<string,string,CancellationToken,Item> probe,CancellationToken token,Action<int> completed){var pairs=new[]{new[]{"ext-ai-claude","api.anthropic.com"},new[]{"ext-ai-openai","api.openai.com"},new[]{"ext-ai-grok","api.x.ai"}};if(token.IsCancellationRequested)return pairs.Select(p=>Result(p[0],"unknown",p[1],"已取消","未执行探测。","需要时重新检查。")).ToList();int done=0;object progressGate=new object();var tasks=new Task<Item>[pairs.Length];for(int index=0;index<pairs.Length;index++){var pair=pairs[index];tasks[index]=Task.Factory.StartNew(delegate{Item item;try{token.ThrowIfCancellationRequested();item=probe(pair[0],pair[1],token);if(item==null)throw new InvalidDataException();if(token.IsCancellationRequested)item=Result(pair[0],"unknown",pair[1],"已取消","未完成不代表服务整体故障。","需要时重新检查。");}catch(Exception e){item=Result(pair[0],"unknown",pair[1],token.IsCancellationRequested?"已取消":e is TimeoutException?"检查超时":"观察失败："+e.GetType().Name,"未完成不代表服务整体故障。","按需检查后重试。");}lock(progressGate){done++;if(completed!=null)try{completed(done);}catch{}}return item;});}Task.WaitAll(tasks);return tasks.Select(t=>t.Result).ToList();}
 public static List<Item> Collect(Report baseline,string privateWorkRoot,CancellationToken token){return Collect(baseline,privateWorkRoot,token,null);}
 public static void CompleteIpv6Window(Report baseline,List<Item> results,Ipv6PathSnapshot after,bool cancelled){var evidence=LocalState.EvaluateIpv6Path(baseline==null?null:baseline.ipv6Before,after);if(cancelled){evidence.status="unknown";evidence.identity="ipv6-path-unverified";evidence.failureCode="cancelled";evidence.observation="完整观察已取消，前后路径证据不能作为当前结论。";}results.Add(evidence);if(cancelled||!LocalState.Ipv6SnapshotsConsistent(baseline==null?null:baseline.ipv6Before,after))foreach(var item in results.Where(i=>i.key=="ext-rtc-compare"&&i.status=="pass")){item.status="unknown";item.failureCode="network-window-unverified";item.observation="浏览器同族比较已观察，但完整采样前后路径或时间不一致；需重新检查。";}}
 public static List<Item> Collect(Report baseline,string privateWorkRoot,CancellationToken token,Action<int,string> progress){if(token.IsCancellationRequested)return new List<Item>();var results=CollectWith(baseline,privateWorkRoot,token,progress,Service,DnsEvidence,AttributeEvidence,BrowserIce.Collect);CompleteIpv6Window(baseline,results,LocalState.CaptureIpv6PathSafe(),token.IsCancellationRequested);return results;}
 public static List<Item> CollectWith(Report baseline,string privateWorkRoot,CancellationToken token,Action<int,string> progress,Func<string,string,CancellationToken,Item> service,Func<CancellationToken,List<Item>> dns,Func<Report,CancellationToken,List<Item>> attributes,Func<Report,string,CancellationToken,List<Item>> browser){var results=new List<Item>();if(token.IsCancellationRequested)return results;if(progress!=null)progress(2,"正在检查 AI 服务连接");results.AddRange(ParallelServices(service,token,delegate(int n){if(progress!=null)progress(2+n,"AI 服务连接已检查 "+n+" / 3");}));if(!token.IsCancellationRequested){if(progress!=null)progress(6,"正在检查 DNS 解析");results.AddRange(dns(token));}if(!token.IsCancellationRequested){if(progress!=null)progress(7,"正在查询出口属性");results.AddRange(attributes(baseline,token));}if(!token.IsCancellationRequested)try{if(progress!=null)progress(8,"正在检查浏览器网络信息");results.AddRange(browser(baseline,privateWorkRoot,token));}catch(Exception e){results.Add(Result("ext-rtc-browser","unknown","隔离浏览器",e is OperationCanceledException?"已取消":"隔离会话创建失败","未完成浏览器观察。","核对私密工作目录权限。"));}return results;}
